// ```go
// t := t"2026-08-29T15:04:05.123456789Z"
// t.string()                 // => "2026-08-29T15:04:05.123456789Z" — the ONE text form, RFC3339Nano
// time(t.string()) == t      // => true — the text form round-trips through the canonical grammar
// ```
