// Answer the civil day the instant falls on in the named zone.
//
// A [`date`](date.md) is a civil day with no zone, so the conversion reads the day in a zone — the time's own, or
// a named one:
//
// ```go
// t := t"2026-03-31T23:30:00Z"
// t.date()                       // => date("2026-03-31") — the civil day in the time's own zone; ≡ date(t)
// t.date_in("Europe/Kyiv")       // => date("2026-04-01") — the same instant is already April 1st in Kyiv
// ```
//
// Near midnight the UTC day and the local day differ — name the zone the business day belongs to. The way back
// is `d.time()` (midnight UTC) or `d.time_in(zone)` (the first instant of the day there).
//
//kavun:member date_in pure (zone) -> date
func timeDateIn(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*time.Time)(v.Ptr)
	// the civil day in a named zone: ≡ t.in_zone(z).date()
	loc, err := zoneArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	y, m, dd := o.In(loc).Date()
	d, err := newDate(y, int(m), dd)
	if err != nil {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) %s", name, err))
	}
	return DateValue(d), nil
}

// Answer the same instant viewed in the named zone.
//
// ```go
// kyiv := t"2026-08-29T12:04:05Z".in_zone("Europe/Kyiv")
//
// kyiv                  // => time("2026-08-29T15:04:05+03:00") — same instant, viewed in Kyiv
// kyiv.zone_name()      // => "EEST"
// kyiv.zone_offset()    // => 10800 — seconds east of UTC
// kyiv.utc()            // => time("2026-08-29T12:04:05Z") — same instant, viewed in UTC
// kyiv.utc().hour()     // => 12
// kyiv.in_zone("")      // Error: invalid_value: (in_zone) a zone name is required
// ```
//
// `in_zone(name)`/`utc()` move the *view*, never the instant. Zone survives arithmetic: `(kyiv + n)` and
// `kyiv.add_days(n)` keep the Kyiv view.
//
//kavun:member in_zone pure (name) -> time
func timeInZone(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*time.Time)(v.Ptr)
	// the same instant, viewed in a named zone
	loc, err := zoneArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	return NewTimeValue(o.In(loc)), nil
}

// Move by `n` calendar days in the value's own zone, keeping the wall clock; see [`add_months`](#add_months).
//
//kavun:member add_days pure (n) -> time
func timeAddDays(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*time.Time)(v.Ptr)
	n, err := parseIntArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	t, err := timeShiftDays(*o, n)
	if err != nil {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) %s", name, err))
	}
	return NewTimeValue(t), nil
}

// Move by `n` calendar months in the value's own zone, keeping the wall clock, with the end-of-month `rule`.
//
// `add_days`, `add_months` and `add_years` move the **calendar** day in the value's own zone and keep the wall
// clock. The end-of-month rule is required — `"clamp"` or `"last_day"`, with no default — and only matters when
// the start is a month end:
//
// ```go
// t"2026-01-31T10:00:00Z".add_months(1, "clamp")      // => time("2026-02-28T10:00:00Z")
// t"2026-04-30T10:00:00Z".add_months(1, "clamp")      // => time("2026-05-30T10:00:00Z")
// t"2026-04-30T10:00:00Z".add_months(1, "last_day")   // => time("2026-05-31T10:00:00Z") — month end stays month end
// t"2023-02-28T00:00:00Z".add_years(1, "last_day")    // => time("2024-02-29T00:00:00Z")
// t"2026-12-31T23:59:59Z".add_days(1)                 // => time("2027-01-01T23:59:59Z")
// t"2026-01-31T10:00:00Z".add_months(1)               // Error: wrong_num_arguments — state the rule
// ```
//
// The kept wall clock follows the one-instant rule: landing in a daylight-saving gap or overlap **raises**.
// UTC and fixed-offset times never do, so moving the arithmetic there is the explicit escape:
//
// ```go
// a := time({year: 2026, month: 3, day: 28, hour: 3, minute: 30, zone: "Europe/Kyiv"})
// a.add_days(1)          // Error: invalid_value: 2026-03-29 03:30:00 does not exist in zone Europe/Kyiv (a daylight-saving gap)
// a.add_days(2)          // => time("2026-03-30T03:30:00+03:00")
// a.utc().add_days(1)    // => time("2026-03-29T01:30:00Z") — exactly 24h later, in UTC
// ```
//
//kavun:member add_months pure (n, rule) -> time
func timeAddMonths(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*time.Time)(v.Ptr)
	n, err := parseIntArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	rule, err := EOMRuleArg(name, "second", args[1])
	if err != nil {
		return Undefined, err
	}
	t, err := timeShiftMonths(*o, n, rule)
	if err != nil {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) %s", name, err))
	}
	return NewTimeValue(t), nil
}

// Move by `n` calendar years in the value's own zone, keeping the wall clock, with the end-of-month `rule`; see
// [`add_months`](#add_months).
//
//kavun:member add_years pure (n, rule) -> time
func timeAddYears(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*time.Time)(v.Ptr)
	// n years is 12n months — checked first, so the multiplication cannot overflow
	n, err := parseIntArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	rule, err := EOMRuleArg(name, "second", args[1])
	if err != nil {
		return Undefined, err
	}
	if n < -1<<31/12 || n > (1<<31-1)/12 {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) result out of range", name))
	}
	t, err := timeShiftMonths(*o, n*12, rule)
	if err != nil {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) %s", name, err))
	}
	return NewTimeValue(t), nil
}

